window.AUTH=window.AUTH||{};window.AUTH["24-440"]={"d":"24-440","id":"2025/24-440","n":"Berk v. Choy","briefs":[{"k":"petitioner","label":"Brief of petitioner Harold R. Berk","date":"2025-05-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-440/359698/20250527151630166_24-440--Berk-%20Merits%20Brief%20with%20Appendix%2005-27%20rtf.pdf","side":"pet","n":100},{"k":"respondent","label":"Brief of respondent Wilson C. Choy, MD","date":"2025-07-30","url":"https://www.supremecourt.gov/DocketPDF/24/24-440/368409/20250730103514425_24-440%20Brief%20for%20Respondent%20Wilson%20C.%20Choy%20MD.pdf","side":"res","n":89},{"k":"respondent","label":"Brief of respondent Beebe Medical Center","date":"2025-07-30","url":"https://www.supremecourt.gov/DocketPDF/24/24-440/368434/20250730134911483_24-440%20Brief%20for%20Respondent%20Beebe%20Medical%20Center.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Harold R. Berk","date":"2025-08-29","url":"https://www.supremecourt.gov/DocketPDF/24/24-440/373200/20250829115413422_24-440%20Berk%20-%20Merits%20Reply%20Brief%20rtf.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us1r10_5hek.pdf","tr":true,"items":[{"t":"case","label":"Abbas v. Foreign Pol’y Grp.","cite":"783 F.3d 1328","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/783/1328/","sum":"Holding Rule 12 is valid because “pleading standards . . . are procedural”.","sumSrc":"brief:0","by":{"0":"10, 24, 29, 32, 39","2":"31-32"}},{"t":"case","label":"Albright v. Christensen","cite":"24 F.4th 1039","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/24/1039/","op":1,"sum":"Finding Michigan’s affidavit-of-merit statute does not apply in federal court because inter alia Rule 8 answers the same question.","sumSrc":"brief:0","by":{"0":"21, 22, 23, 24, 25, 26, 29","2":"19-20","3":"14"}},{"t":"case","label":"Beckett v. Beebe Med. Ctr., Inc.","cite":"897 A.2d 753","y":2006,"court":"Del.","url":"https://www.courtlistener.com/c/A.2d/897/753/","by":{"0":"14","2":"23, 41"}},{"t":"case","label":"Bell Atl. Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"op":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Burlington N. R. Co. v. Woods","cite":"480 U.S. 1","y":1987,"id":"1986/85-1088","sc":1,"op":4,"sum":"The Alabama mandatory affirmance penalty statute has no application to judgments entered by federal courts sitting in diversity.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 12, 27, 28, 29, 30, 31","1":"12, 14, 19, 22, 23, 35, 51","2":"10-11, 14, 22, 28, 32","3":"4, 8"}},{"t":"case","label":"Bus. Guides, Inc. v. Chromatic Commc’ns Enters.","cite":"498 U.S. 533","y":1991,"id":"1990/89-1500","sc":1,"op":2,"sum":"Federal Rule of Civil Procedure 11 provides, in relevant part, that \"[t]he signature of an attorney or party constitutes a certificate by the sigfier that the signer has read the pleading, motion, or other paper\" and \"to the best of the signer's knowledge, information, and belief formed after reasonable inquiry it is well grounded in fact,\" and that a court shall impose an appropriate sanction \"upon the person who …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 27, 28, 29","1":"15, 31, 34","3":"8, 12"}},{"t":"case","label":"Byrd v. Blue Ridge Rural Elec. Coop.","cite":"356 U.S. 525","y":1958,"id":"1957/57","sc":1,"sum":"The Court held that a South Carolina law was essentially a procedural rule because it determined how immunity should be enforced, rather than affecting the substantive rights and obligations created by the state.","sumSrc":"Oyez","by":{"0":"13","1":"14, 24-27, 46","2":"43"}},{"t":"case","label":"Carbone v. Cable News Network, Inc.","cite":"910 F.3d 1345","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/910/1345/","by":{"0":"21, 39"}},{"t":"case","label":"Chamberlain v. Giampapa","cite":"210 F.3d 154","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/210/154/","by":{"0":"30, 31","1":"40, 45","2":"26, 33, 42-43"}},{"t":"case","label":"Cooke v. Jackson Nat’l Life Ins. Co.","cite":"919 F.3d 1024","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/919/1024/","by":{"0":"21"}},{"t":"case","label":"Corley v. United States","cite":"11 F.4th 79","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/11/79/","by":{"0":"22, 39"}},{"t":"case","label":"Dishmon v. Fucci","cite":"32 A.3d 338","y":2011,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/32/338/","op":1,"ar":1,"sum":"Describing § 6853 as imposing a “prima facie evidentiary requiremen[t]”.","sumSrc":"opinion","by":{"0":"14, 15","1":"7, 17, 39, 42, 43, 49","2":"i, 5, 23-24, 26, 28, 41-43"}},{"t":"case","label":"Duross v. Connections CSP, Inc.","cite":"2019 WL 4391231","y":2019,"court":"Del. Super. Ct. Sept. 13","by":{"0":"15"}},{"t":"case","label":"Erickson v. Pardus","cite":"551 U.S. 89","y":2007,"id":"2006/06-7317","sc":1,"sum":"The Court decided that a plaintiff can sufficiently allege that he suffered substantial harm by being denied medical treatment while incarcerated for the purpose of a claim under 42 U.S.C 1983.","sumSrc":"Oyez","by":{"0":"19, 20"}},{"t":"case","label":"(v) Cases—Continued Erie R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"op":2,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"0":"2, 7, 8, 11, 12, 33, 34, 40, 43","1":"2, 13, 15-17, 22, 25, 28, 29, 35, 43, 46","2":"9, 13-14, 21, 32, 35, 42-44"}},{"t":"case","label":"Est. of C.A. v. Grier","cite":"752 F. Supp. 2d 763","y":2010,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/752/763/","by":{"0":"37"}},{"t":"case","label":"Farzana K. v. Ind. Dep’t of Educ.","cite":"473 F.3d 703","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/473/703/","by":{"0":"24","2":"20","3":"14"}},{"t":"case","label":"Gallivan v. United States","cite":"943 F.3d 291","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/291/","op":2,"by":{"0":"10, 12-13, 21-22, 24, 29, 39","2":"25","3":"3, 5, 6"}},{"t":"case","label":"Gasperini v. Ctr. for Humans., Inc.","cite":"518 U.S. 415","y":1996,"id":"1995/95-719","sc":1,"op":7,"ar":4,"sum":"In a split majority decision, authored by Justice Ruth Bader Ginsburg, the Court ruled that New York's law controlling compensation awards for excessiveness or inadequacy can be given effect, without detriment to the Seventh Amendment, if the review standard is applied by the federal trial court judge, with appellate control of the trial court's ruling confined to \"abuse of discretion.\" Justice John Paul Stevens dissented regarding the judgment of the Court but agreed with most of the majority's reasoning.","sumSrc":"Oyez","by":{"0":"12-13, 42","1":"15, 25-28","2":"14, 19, 35, 44"}},{"t":"case","label":"Gates v. L.G. DeWitt, Inc.","cite":"528 F.2d 405","y":1976,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/528/405/","sum":"Finding Georgia law requiring plaintiff to attach insurance contract to complaint inapplicable based on conflict with Rule 8.","sumSrc":"brief:0","by":{"0":"37"}},{"t":"case","label":"Guaranty Tr. Co. v. York","cite":"326 U.S. 99","y":1945,"id":"scdb/1944-101","sc":1,"op":1,"sum":"In a suit in equity in a federal court to recover upon a State-created right, jurisdiction being based solely upon diversity of citizenship of the parties, a recovery can not be had if a state statute of' limitations would have barred recovery had the suit been brought in a court of the State. Erie R. Co. v. Tompkins, 304 U. S.64, followed. P. 108. 143 F. 2d 503, reversed. CEanoRA, 323 U. S. 693, to review the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 28, 29","1":"25, 50"}},{"t":"case","label":"Hall v. Sorouri","cite":"996 A.2d 793","y":2010,"court":"Del.","url":"https://www.courtlistener.com/c/A.2d/996/793/","op":1,"by":{"0":"15"}},{"t":"case","label":"Hanna v. Plumer","cite":"380 U.S. 460","y":1965,"id":"1964/171","sc":1,"op":6,"ar":11,"sum":"The Court ruled for Hanna. To raise the Erie doctrine, the Court reasoned, the effect of a procedural rule on the outcome of a case must abridge, enlarge, or modify the substantive law. There was no change to a substantive right here because the plaintiff simply could refile the case or serve the defendant personally.","sumSrc":"Oyez","by":{"0":"9, 13, 22, 27, 28, 33","1":"2, 3, 12, 14-16, 18-30, 35, 47","2":"13-14, 22, 33, 35, 42","3":"3, 8"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"op":14,"sum":"Noting that we have “rejected every statutory challenge to a Federal Rule that has come before us”.","sumSrc":"opinion","by":{"0":"38"}},{"t":"case","label":"Hilderman v. Enea TekSci, Inc.","cite":"2010 WL 143440","y":2010,"court":"S.D. Cal. Jan. 8","sum":"Holding California statute that conditions discovery regarding trade secrets on plaintiff identifying the trade secret “with reasonable particularity” is inapplicable in federal court.","sumSrc":"brief:0","by":{"0":"37"}},{"t":"case","label":"Hill v. McDonough","cite":"547 U.S. 573","y":2006,"id":"2005/05-8794","sc":1,"sum":"The Supreme Court held that challenging the form of execution was fundamentally different from challenging the lawfulness of a conviction or sentence, the traditional purposes of a habeas corpus appeal.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Jennings v. Rodriquez","cite":"583 U.S. 281","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/281/","sc":1,"by":{"0":"18"}},{"t":"case","label":"Johnson v. City of Shelby","cite":"574 U.S. 10","y":2014,"id":"2014/13-1318","sc":1,"sum":"The Court held that federal pleading rules require only a “short plain statement of the claim showing that the pleader is entitled to relief,” not a complete statement of the legal theory supporting the claim.","sumSrc":"Oyez","by":{"0":"19, 20"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"op":2,"sum":"Rejecting requirement that prisoners “attach proof of exhaustion . . . to their complaints” as inconsistent with Rule 8.","sumSrc":"opinion","by":{"0":"19, 43"}},{"t":"case","label":"Kalinowski v. Adams","cite":"2012 WL 1413999","y":2012,"court":"Del. Super. Ct. Mar. 9","by":{"0":"15","2":"24"}},{"t":"case","label":"Kirkland v. Guardian Life Ins. Co. of Am.","cite":"352 F. App’x 293","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/352/293/","sum":"Holding that Georgia law requiring a verified answer when a complaint is verified conflicts with Federal Rule of Civil Procedure 11(a) and thus does not apply in federal court.","sumSrc":"brief:0","by":{"0":"37"}},{"t":"case","label":"Klocke v. Watson","cite":"936 F.3d 240","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/936/240/","by":{"0":"24, 39, 41"}},{"t":"case","label":"Lapides v. Bd. of Regents of Univ. Sys. of Georgia","cite":"535 U.S. 613","y":2002,"id":"2001/01-298","sc":1,"sum":"The Court held that a State waives its Eleventh Amendment immunity when it removes a case from state court to federal court.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Leatherman v. Tarrant Cnty. Narcotics Intelligence & Coordination Unit","cite":"507 U.S. 163","y":1993,"id":"1992/91-1657","sc":1,"op":3,"sum":"L A federal court may not apply a \"heightened pleading standard\"more stringent than the usual pleading requirements of Federal Rule of Civil Procedure 8(a)-in civil rights cases alleging municipal liability under § 1983. First, the heightened standard cannot be justified on the ground that a more relaxed pleading standard would eviscerate municipalities' immunity from suit by subjecting them to expensive and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 20, 43","2":"27"}},{"t":"case","label":"Loper Bright Enters. v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35","1":"34","2":"18","3":"16"}},{"t":"case","label":"Love v. United States","cite":"17 F.4th 753","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/17/753/","sum":"Finding Rule 26, along with federal evidentiary rules, is the “source of authority to control expert evidence” and “specifies when and how expert evidence must be produced”.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Makaeff v. Trump Univ., LLC","cite":"715 F.3d 254","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/715/254/","by":{"0":"32, 33, 40, 41"}},{"t":"case","label":"Mammarella v. Evantash","cite":"93 A.3d 629","y":2014,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/93/629/","sum":"Explaining that § 6853 “limits the use of an affidavit of merit, barring the defense from even discovering [it] and precluding [its] use … as evidence”.","sumSrc":"brief:1","by":{"0":"14","1":"6, 17, 38, 41, 42, 47","2":"31"}},{"t":"case","label":"Martin v. Pierce County","cite":"34 F.4th 1125","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/34/1125/","by":{"0":"22, 29"}},{"t":"case","label":"Miss. Publ’g Corp. v. Murphree","cite":"326 U.S. 438","y":1946,"id":"scdb/1945-120","sc":1,"op":3,"sum":"Respondent, a resident of the northern district of Mississippi, brought suit in the federal district court for that district against petitioner, a Delaware corporation having an office and place of business in the southern district of Mississippi, to recover damages in an amount exceeding $3,000 for libel published in the southern district. The suit was begun by service of summons in the southern district by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 29","1":"51","3":"7, 8"}},{"t":"case","label":"Navarro Sav. Ass’n v. Lee","cite":"446 U.S. 458","y":1980,"id":"1979/79-465","sc":1,"op":3,"sum":"Respondents, as individual trustees of a business trust organized under Massachusetts law, may invoke the diversity jurisdiction of the federal courts on the basis of their own citizenship without regard to the citizenship of the trust beneficiaries. A federal court must rest jurisdiction only upon the citizenship of real parties to the controversy, and a trustee is a real party to the controversy for purposes of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Nichols v. Christiana Care Health Sys.","cite":"266 A.3d 976","y":2021,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/266/976/","sum":"Rejecting affidavit of merit because it stated nurse was “certified,” instead of “licensed” as § 6853(c) requires.","sumSrc":"brief:0","by":{"0":"15"}},{"t":"case","label":"Nuveen Mun. Tr. ex rel. Nuveen High Yield Mun. Bond Fund v. WithumSmith Brown, P.C.","cite":"692 F.3d 283","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/692/283/","by":{"0":"40, 41","2":"26, 28, 34"}},{"t":"case","label":"Palacio ex rel. Mitchell v. Premier Healthcare, Inc.","cite":"2015 WL 13697664","y":2015,"court":"Del. Super. Ct. Aug. 11","sum":"Rejecting affidavit of merit because it failed to state in “simple, clear language” that the defendant’s “negligence proximately caused [the plaintiff’s] injuries”.","sumSrc":"brief:0","by":{"0":"15","2":"24"}},{"t":"case","label":"Passmore v. Baylor Health Care Sys.","cite":"823 F.3d 292","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/823/292/","sum":"Concluding that “Rules 26 and 37 are valid under the Rules Enabling Act”.","sumSrc":"brief:0","by":{"0":"26, 27, 29"}},{"t":"case","label":"Pledger v. Lynch","cite":"5 F.4th 511","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/5/511/","op":2,"by":{"0":"13, 22-25, 29, 31, 39","1":"28, 35, 37, 43","2":"26, 28","3":"3, 4, 6"}},{"t":"case","label":"Royalty Network, Inc. v. Harris","cite":"756 F.3d 1351","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1351/","by":{"0":"24","1":"30","2":"19-20","3":"14"}},{"t":"case","label":"Sanders v. Centurion L.L.C.","cite":"319 A.3d 307","y":2024,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/319/307/","by":{"0":"15"}},{"t":"case","label":"Schlagenhauf v. Holder","cite":"379 U.S. 104","y":1964,"id":"1964/8","sc":1,"sum":"A bus collided with the rear of a tractor-trailer and a diversity action for damages was brought by certain bus passengers in the District Court. The defendants-the bus company, petitioner its driver, the owners of the tractor and the trailer (hereinafter codefendants), and the tractor driver-filed answers denying negligence. The bus company cross-claimed against codefendants for damage to its bus, claiming that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","3":"8"}},{"t":"case","label":"Schmigel v. Uchal","cite":"800 F.3d 113","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/800/113/","by":{"0":"40","2":"10"}},{"t":"case","label":"Shady Grove Orthopedic Assocs., P.A. v. Allstate Ins. Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"op":16,"ar":16,"sum":"Noting that we have “rejected every statutory challenge to a Federal Rule that has come before us”.","sumSrc":"opinion","by":{"0":"2-3, 8-13, 16, 21-22, 27-31, 33-35, 37-39, 41-43","1":"2, 3, 12, 14, 15, 18-20, 23, 27-29, 34, 35, 48-52","2":"2, 10-11, 14, 18-19, 22, 32, 37-38, 40-42","3":"3, 4, 7, 8, 19, 20"}},{"t":"case","label":"Sibbach v. Wilson & Co.","cite":"312 U.S. 1","y":1941,"id":"scdb/1940-046","sc":1,"op":5,"sum":"1. Congress has power to regulate the practice and procedure of federal courts, and may exercise it by delegating to the Supreme or other federal courts authority to make rules not inconsistent with the statutes or Constitution of the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","1":"17, 48, 50","2":"39-40"}},{"t":"case","label":"Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"sum":"The Court held that the district court has maritime jurisdiction when the incident in question represents a potential hazard to maritime commerce and bears a substantial relationship to maritime activity.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Skinner v. Switzer","cite":"562 U.S. 521","y":2011,"id":"2010/09-9000","sc":1,"sum":"The Court held that a convicted prisoner seeking access to biological evidence for DNA testing may assert that claim in a civil rights action under 42 U.S.C. § 1983.","sumSrc":"Oyez","by":{"0":"18, 19, 20"}},{"t":"case","label":"Smith v. Kobasa","cite":"113 A.3d 1081","y":2015,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/113/1081/","by":{"0":"14, 15"}},{"t":"case","label":"Standard Fire Ins. Co. v. Knowles","cite":"568 U.S. 588","y":2013,"id":"2012/11-1450","sc":1,"sum":"The Court held that a plaintiff in a class action case cannot stipulate that the potential damages are less than $5 million in order to remove the case from federal jurisdiction.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Steward v. Irgau","cite":"2019 WL 2743714","y":2019,"court":"Del. Super. Ct. June 21","by":{"0":"14"}},{"t":"case","label":"Stewart Org., Inc. v. Ricoh Corp.","cite":"487 U.S. 22","y":1988,"id":"1987/86-1908","sc":1,"sum":"Petitioner company, an Alabama corporation, entered into a dealership agreement to market copier products of respondent, a nationwide manufacturer with its principal place of business in New Jersey. The agreement contained a clause providing that any dispute arising out of the contract could be brought only in a court located in Manhattan in New York City. Petitioner company (and the individual stockholder …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"20, 23, 34","2":"14"}},{"t":"case","label":"Swierkiewicz v. Sorema, N.A.","cite":"534 U.S. 506","y":2002,"id":"2001/00-1853","sc":1,"op":2,"sum":"The Court held that an employment discrimination complaint need not include specific facts establishing a prima facie case under the framework of McDonnell Douglas Corp. v. Green and instead must contain only \"a short and plain statement of the claim showing that the pleader is entitled to relief,\" pursuant to Rule 8(a)(2) of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Tutor Time Child Care Sys., Inc. v. Franks Inv. Grp., Inc.","cite":"966 F. Supp. 1188","y":1997,"court":"S.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp./966/1188/","by":{"0":"37"}},{"t":"case","label":"Tyra v. Organ Procurement Agency of Mich.","cite":"869 N.W.2d 213","y":2015,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/869/213/","by":{"0":"23"}},{"t":"case","label":"Walker v. Armco Steel Corp.","cite":"446 U.S. 740","y":1980,"id":"1979/78-1862","sc":1,"op":6,"sum":"The action is barred by the Oklahoma statute of limitations. Ragan, supra.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 30","1":"32, 50","2":"10-11, 14, 22, 25, 27"}},{"t":"case","label":"Woods v. Interstate Realty Co.","cite":"337 U.S. 535","y":1949,"id":"scdb/1948-100","sc":1,"op":3,"sum":"The motion for summary judgment was properly granted. Erie R. Co. v. Tompkins, 304 U. S.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 43","1":"27","2":"27, 29, 44","3":"4, 5"}},{"t":"case","label":"Young v. United States","cite":"942 F.3d 349","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/942/349/","op":2,"by":{"0":"21","1":"15, 26, 27","2":"12, 33-34"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"18, 19"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","subs":["(a)","(b)"],"stext":{"head":"§2072. Rules of procedure and evidence; power to prescribe","paras":[[0,"(a) The Supreme Court shall have the power to prescribe general rules of practice and procedure and rules of evidence for cases in the United States district courts (including proceedings before magistrate judges thereof) and courts of appeals."],[0,"(b) Such rules shall not abridge, enlarge or modify any substantive right. All laws in conflict with such rules shall be of no further force or effect after such rules have taken effect."],[0,"(c) Such rules may define when a ruling of a district court is final for the purposes of appeal under section 1291 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2072?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2072. Rules of procedure and evidence; power to prescribe","tname":"Judiciary and Judicial Procedure","by":{"0":"12, 28, 28","1":"48, 17, 48, 51, 52"}},{"t":"rule","label":"Fed. R. Civ. P. 1","url":"https://www.law.cornell.edu/rules/frcp/rule_1","by":{"0":"36"}},{"t":"rule","label":"Fed. R. Civ. P. 3","url":"https://www.law.cornell.edu/rules/frcp/rule_3","by":{"0":"3, 9, 10, 23, 25, 27, 29","1":"16, 21, 35, 36, 37, 50","2":"10, 27, 36"}},{"t":"rule","label":"Fed. R. Civ. P. 4","url":"https://www.law.cornell.edu/rules/frcp/rule_4","subs":["(d)(1)","(f)","(e)","(h)"],"by":{"0":"28, 28","1":"32, 32, 32, 32","2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 8","url":"https://www.law.cornell.edu/rules/frcp/rule_8","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(c)"],"by":{"0":"2, 7-10, 13, 16-23, 27-31, 37, 43, 16, 31, 37, 16, 18, 19, 16","1":"12, 16, 35, 37, 38, 39, 50, 21","2":"2, 9-11, 25-27, 30, 33"}},{"t":"rule","label":"Fed. R. Civ. P. 9","url":"https://www.law.cornell.edu/rules/frcp/rule_9","subs":["(b)","(g)"],"by":{"0":"2, 8-10, 13, 17-23, 27-29, 31, 43, 17, 18, 37","1":"12, 16, 35, 37, 38, 39, 50","2":"2, 9-11, 25, 27"}},{"t":"rule","label":"Fed. R. Civ. P. 11","url":"https://www.law.cornell.edu/rules/frcp/rule_11","subs":["(a)","(b)","(b)(2)","(b)(3)","(c)"],"by":{"0":"3, 7, 9-10, 22-25, 27-29, 32, 24, 37, 25, 25, 25, 25","1":"12, 15, 16, 30, 31, 32, 35, 39, 40, 50, 15, 16, 29, 30, 31, 32, 33, 34, 35, 38, 39, 16, 31, 39, 16, 39, 5","2":"1-2, 9-11, 15-21, 28-29"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(a)","(d)"],"by":{"0":"3, 7, 9-10, 22-24, 27-29, 32, 40","1":"12, 16, 17, 27, 35, 41, 50, 32, 37","2":"9-11, 16, 27, 29, 31-32, 36"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"0":"29, 34","1":"23, 48","2":"17, 22, 39"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","subs":["(a)","(a)(2)(D)","(a)(1)","(a)(1)(B)(ii)","(a)(2)(B)"],"by":{"0":"3, 9, 10, 23, 25, 26, 27, 28, 29, 26, 26","1":"17, 35, 41, 42, 50, 10, 32, 42","2":"8, 10, 12, 17, 31-32"}},{"t":"rule","label":"Fed. R. Civ. P. 35","url":"https://www.law.cornell.edu/rules/frcp/rule_35","by":{"0":"28","2":"40"}},{"t":"rule","label":"Fed. R. Civ. P. 37","url":"https://www.law.cornell.edu/rules/frcp/rule_37","subs":["(c)"],"by":{"0":"3, 9, 10, 23, 25, 27, 28, 29, 27","1":"17, 35, 41, 42, 50","2":"10, 12, 32, 40"}},{"t":"rule","label":"Fed. R. Civ. P. 38","url":"https://www.law.cornell.edu/rules/frcp/rule_38","by":{"0":"28","2":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","by":{"0":"10, 32","1":"15, 26"}},{"t":"rule","label":"Fed. R. Civ. P. 81","url":"https://www.law.cornell.edu/rules/frcp/rule_81","by":{"0":"36","2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 84","url":"https://www.law.cornell.edu/rules/frcp/rule_84","by":{"0":"17, 17"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Barrow v. Wexford Health Sources, Inc.","cite":"793 F. App’x 420","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/793/420/","sum":"Holding that an affidavit-of-merit requirement “reflects Illinois’s ‘substantive’ law of negligence” but need not be enforced through pleading rules.","sumSrc":"brief:1","by":{"1":"26"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"sum":"The District Court properly invoked its inherent power in assessing as a sanction for Chambers' bad-faith conduct the attorney's fees and related expenses paid by NASCO.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40","2":"28"}},{"t":"case","label":"Ciomber v. Coop. Plus, Inc.","cite":"527 F.3d 635","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/527/635/","by":{"1":"42"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"op":7,"ar":6,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 28","2":"27, 29-30, 44","3":"4, 5"}},{"t":"case","label":"Connolly v. Foudree","cite":"141 F.R.D. 124","y":1992,"court":"S.D. Iowa","url":"https://www.courtlistener.com/c/F.R.D./141/124/","by":{"1":"46"}},{"t":"case","label":"Hahn v. Walsh","cite":"762 F.3d 617","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/762/617/","by":{"1":"40, 41"}},{"t":"case","label":"HSBC Bank USA v. Lombardo","cite":"2020 WL 6136213","y":2020,"court":"D. Me.","by":{"1":"33"}},{"t":"case","label":"Jones v. Corr. Med. Servs., Inc.","cite":"845 F. Supp. 2d 824","y":2012,"court":"W.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/845/824/","by":{"1":"37-38, 44, 45"}},{"t":"case","label":"Kanouse v. Westwood Obstetrical & Gyn. Assocs.","cite":"505 F. Supp. 129","y":1981,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./505/129/","by":{"1":"45"}},{"t":"case","label":"Liggon-Redding v. Estate of Sugarman","cite":"659 F.3d 258","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/659/258/","by":{"1":"13, 37, 44","2":"9, 30, 42"}},{"t":"case","label":"McBride v. Shipley Manor Health Care","cite":"2005 WL 2090695","y":2005,"court":"Del. Super. Mar. 23","by":{"1":"36"}},{"t":"case","label":"Meloney v. Nanticoke Gastroenterology, P.A. and Mackler, C.A. No. 06C-05-006 THG","cite":"2006 WL 2329377","y":2006,"court":"Del. Super. July 18","by":{"1":"36"}},{"t":"case","label":"Mississippi Phosphates Corp. v. Analytic Stress Relieving, Inc.","cite":"402 F. App’x 866","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/402/866/","op":9,"by":{"1":"33"}},{"t":"case","label":"Muldrow v. City of St. Louis, Missouri","cite":"601 U.S. 346","y":2024,"id":"2023/22-193","sc":1,"sum":"An employee challenging a job transfer under Title VII must show that the transfer brought about some harm with respect to an identifiable term or condition of employment, but that harm need not be significant.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Palmer v. Hoffman","cite":"318 U.S. 109","y":1943,"id":"scdb/1942-169","sc":1,"sum":"1. A signed statement of a railroad engineer, since deceased, giving his version of a grade crossing accident in which the locomotive he was operating was involved, and made, two days after the accident, when he was interviewed by an official of the company and a representative of a state commission, held not made \"in the regular course\" of business within the meaning of the Act of June 20, 1936, and not admissible …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Pegram v. Herdrich","cite":"530 U.S. 211","y":2000,"id":"1999/98-1949","sc":1,"sum":"The Court held that mixed treatment and eligibility decisions to delay medical treatment by sending a patient to a HMO owned facility, with adverse consequences, made by a health maintenance organization through its physician, are not fiduciary decisions under ERISA.","sumSrc":"Oyez","by":{"1":"4, 46"}},{"t":"case","label":"Ragan v. Merchants Transfer & Warehouse Co.","cite":"337 U.S. 530","y":1949,"id":"scdb/1948-099","sc":1,"op":2,"sum":"The suit was barred by the state statute of limitations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"31, 34"}},{"t":"case","label":"RTC Mortg. Trust 1994 N-1 v. Fidelity Nat. Title Ins. Co.","cite":"981 F. Supp. 334","y":1997,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp./981/334/","by":{"1":"45","2":"20"}},{"t":"case","label":"Scott v. Sanders","cite":"789 F. Supp. 2d 773","y":2011,"court":"E.D. Ky.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/789/773/","by":{"1":"40"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"ar":1,"sum":"The Court held that \"[b]ecause the claim-preclusive effect of a federal court's dismissal 'upon the merits' of a diversity action on state statute-of-limitations grounds is governed by a federal rule, which in turn (in diversity cases) incorporates the claim-preclusion law that would be applied by state courts in the State in which the federal court sits, the Maryland Court of Special Appeals erred in holding that the California federal court's dismissal 'upon the merits' necessarily precluded the Maryland state-court action.\" Thus, the District Court's dismissal on the merits of claims as untimely under California law did not preclude Semtek from asserting its claims in a different state court forum.","sumSrc":"Oyez","by":{"1":"22, 23, 28, 43, 46-48, 51","2":"10, 41-42"}},{"t":"case","label":"Thompson by Thompson v. Kishwaukee Valley Med. Grp.","cite":"1986 WL 11381","y":1986,"court":"N.D. Ill. Oct. 6","by":{"1":"31","2":"20"}},{"t":"case","label":"Trierweiler v. Croxton and Trench Holding Corp.","cite":"90 F.3d 1523","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/90/1523/","by":{"1":"45","2":"29, 33, 43"}},{"t":"case","label":"Tusha v. Pediatric Assocs.","cite":"2023 WL 5932921","y":2023,"court":"D. Del. Sept. 12","by":{"1":"38"}},{"t":"usc","label":"28 U.S.C. § 1404","url":"https://www.law.cornell.edu/uscode/text/28/1404","subs":["(a)"],"by":{"1":"34"}},{"t":"usc","label":"42 U.S.C. § 11131","url":"https://www.law.cornell.edu/uscode/text/42/11131","by":{"1":"44"}},{"t":"reg","label":"45 C.F.R. § 60.7","url":"https://www.ecfr.gov/current/title-45/section-60.7","subs":["(a)"],"by":{"1":"44"}},{"t":"rule","label":"Fed. R. App. P. 38","url":"https://www.law.cornell.edu/rules/frap/rule_38","by":{"1":"22"}},{"t":"rule","label":"Fed. R. Civ. P. 7","url":"https://www.law.cornell.edu/rules/frcp/rule_7","by":{"1":"37","2":"26"}},{"t":"rule","label":"Fed. R. Civ. P. 15","url":"https://www.law.cornell.edu/rules/frcp/rule_15","subs":["(b)(1)"],"by":{"1":"37, 38"}},{"t":"rule","label":"Fed. R. Civ. P. 16","url":"https://www.law.cornell.edu/rules/frcp/rule_16","subs":["(c)"],"by":{"1":"33"}},{"t":"rule","label":"Fed. R. Civ. P. 17","url":"https://www.law.cornell.edu/rules/frcp/rule_17","subs":["(a)"],"by":{"1":"33, 33","2":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 24","url":"https://www.law.cornell.edu/rules/frcp/rule_24","subs":["(a)(1)","(a)(1)(B)(ii)"],"by":{"1":"32, 32","2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 40","url":"https://www.law.cornell.edu/rules/frcp/rule_40","by":{"1":"32","2":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 41","url":"https://www.law.cornell.edu/rules/frcp/rule_41","subs":["(b)"],"by":{"1":"52, 22","2":"17, 30"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(d)(1)"],"by":{"1":"32","2":"16-17, 19"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","subs":["(e)(1)"],"by":{"1":"32, 32, 32","2":"17"}},{"t":"case","label":"Amchem Prods., Inc. v. Windsor","cite":"521 U.S. 591","y":1997,"id":"1996/96-270","sc":1,"sum":"In resolving the case the Court declined to reach the issue of whether the settlement proceeding was a justiciable case or controversy under Article III because, it held, determination of class certification was logically antecedent to these issues.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"2":"30","3":"5"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Burke v. Air Serv Int’l, Inc.","cite":"685 F.3d 1102","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/685/1102/","by":{"2":"43"}},{"t":"case","label":"Citizens for Resp. & Ethics in Washington v. FEC","cite":"971 F.3d 340","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/971/340/","by":{"2":"16"}},{"t":"case","label":"Dambro v. Meyers","cite":"974 A.2d 121","y":2009,"court":"Del.","url":"https://www.courtlistener.com/c/A.2d/974/121/","by":{"2":"40"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"Follenfant v. Rogers","cite":"359 F.2d 30","y":1966,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/359/30/","by":{"2":"20"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Lamie v. U.S. Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"McFadden v. United States","cite":"576 U.S. 186","y":2015,"id":"2014/14-378","sc":1,"sum":"The Court decided that in order to fulfill the intent element of The Controlled Substance Analogue Enforcement Act of 1986, a person must either know that the substance is a controlled substance or be aware of what the substance is without knowing that it is controlled.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Milam v. State Farm Mut. Auto. Ins. Co.","cite":"972 F.2d 166","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/972/166/","by":{"2":"43"}},{"t":"case","label":"Moody v. NetChoice, LLC","cite":"603 U.S. 707","y":2024,"id":"2023/22-277","sc":1,"sum":"The judgments are vacated, and the cases are remanded, because neither the Eleventh Circuit nor the Fifth Circuit conducted a proper analysis of the facial First Amendment challenges to the Florida and Texas laws regulating large internet platforms.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"38"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Morrison v. Nat’l Austl. Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"op":1,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Neitzke v. Williams","cite":"490 U.S. 319","y":1989,"id":"1988/87-1882","sc":1,"sum":"A complaint filed in forma pauperis is not automatically frivolous within the meaning of § 1915(d) because it fails to state a claim under Rule 12(b)(6). The two standards were devised to serve distinctive goals and have separate functions. Under Rule 12(b)(6)'s failure-tostate-a-claim standard-which is designed to streamline litigation by dispensing with needless discovery and factfinding-a court may dismiss a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30-31"}},{"t":"case","label":"viii Passmore v. Baylor Health Care Sys.","cite":"841 F.3d 284","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/841/284/","sum":"Explaining the “unique purpose” of Texas’s affidavit-of-merit requirement “separate and apart from the procedural rules relating to discovery and typical expert reports”.","sumSrc":"brief:2","by":{"2":"32"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"16"}},{"t":"case","label":"Romero v. Int’l Terminal Operating Co.","cite":"79 S. Ct. 468","y":1959,"url":"https://www.courtlistener.com/c/S.%20Ct./79/468/","sc":1,"by":{"2":"36"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"583 U.S. 202","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"sum":"The Clean Water Act extends only to wetlands that have a continuous surface connection with “waters” of the United States—i.e., with a relatively permanent body of water connected to traditional interstate navigable waters, 33 U. S. C. §1362(7)—making it difficult to determine where the water ends and the wetland begins.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"Tome v. United States","cite":"513 U.S. 150","y":1995,"id":"1994/93-6892","sc":1,"sum":"The Court held that Rule 801(d)(1)(B) requires that prior consistent statements be made before the motive to fabricate arose in order to be admissible.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Tyson Foods, Inc. v. Bouaphakeo","cite":"577 U.S. 442","y":2016,"id":"2015/14-1146","sc":1,"sum":"The Court determined that a class action is properly certified and maintained, despite differences among the plaintiff class, if all the individual plaintiffs' cases ask the same central question and even if some plaintiffs were not injured and have no legal right to damages.","sumSrc":"Oyez","by":{"2":"39","3":"8"}},{"t":"case","label":"Vareha v. Beebe Med. Ctr., Inc.","cite":"2011 WL 2361270","y":2011,"court":"Del. Super. Ct. May 26","by":{"2":"24"}},{"t":"case","label":"Velazquez v. UPMC Bedford Mem’l Hosp.","cite":"328 F. Supp. 2d 549","y":2004,"court":"W.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/328/549/","by":{"2":"20"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"2":"39","3":"8"}},{"t":"case","label":"West v. Am. Tel. & Tel. Co.","cite":"311 U.S. 223","y":1940,"id":"scdb/1940-038","sc":1,"op":1,"sum":"(1) No reason appears for supposing that, if the second suit had been brought in a state court, the state Court of Appeals would depart from its previous ruling or that the Supreme Court of the State would grant the review which it withheld before. P. 238. (2) The law thus announced and applied by the state Court of Appeals is the law of the State, applicable to a case between the jame parties in the federal court; …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"rule","label":"Fed. R. Civ. P. 4.1","url":"https://www.law.cornell.edu/rules/frcp/rule_4.1","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 5.1","url":"https://www.law.cornell.edu/rules/frcp/rule_5.1","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 6","url":"https://www.law.cornell.edu/rules/frcp/rule_6","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 39","url":"https://www.law.cornell.edu/rules/frcp/rule_39","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 43","url":"https://www.law.cornell.edu/rules/frcp/rule_43","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 53","url":"https://www.law.cornell.edu/rules/frcp/rule_53","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 64","url":"https://www.law.cornell.edu/rules/frcp/rule_64","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 69","url":"https://www.law.cornell.edu/rules/frcp/rule_69","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 71.1","url":"https://www.law.cornell.edu/rules/frcp/rule_71.1","by":{"2":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 83","url":"https://www.law.cornell.edu/rules/frcp/rule_83","by":{"2":"17"}},{"t":"case","label":"Ariz. State Legislature v. Ariz. Indep. Redistricting Comm’n","cite":"576 U.S. 787","y":2015,"id":"2014/13-1314","sc":1,"sum":"The Court determined that the Elections Clause of the U.S. Constitution does not prohibit a state from creating an independent redistricting commission by initiative.","sumSrc":"Oyez","by":{"3":"12, 13"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"sum":"The Secretary of Education does not have authority under the Higher Education Relief Opportunities for Students Act of 2003 (HEROES Act) to establish a student loan forgiveness program that will cancel roughly $430 billion in debt principal and affect nearly all borrowers.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"9, 15"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"590 U.S. 644","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Employers Mut. Lib. Ins. Co. of Wis. v. Blunt","cite":"227 F.2d 312","y":1955,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/227/312/","by":{"3":"14"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"3":"9, 10"}},{"t":"case","label":"FDA v. R. J. Reynolds Vapor Co.","cite":"145 S. Ct. 1984","y":2025,"id":"2024/23-1187","sc":1,"sum":"Retailers who would sell a new tobacco product if not for the FDA’s denial order may seek judicial review of that order under 21 U. S. C. §387l(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"3":"12"}},{"t":"case","label":"Gundy v. United States","cite":"588 U.S. 128","y":2019,"id":"2018/17-6086","sc":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"case","label":"Jerome v. United States","cite":"318 U.S. 101","y":1943,"id":"scdb/1942-126","sc":1,"sum":"In § 2 (a) of the federal Bank Robbery Act, which provides that \"whoever shall enter or attempt to enter any bank, or any building used in whole or in part as a bank, with intent to commit in such bank or building, or part thereof, so used, any felony or larceny\" shall be subject to the penalty therein prescribed, the word \"felony\" embraces only offenses which are felonies under federal law and affect banks …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"Joe v. United States","cite":"772 F.2d 1535","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/772/1535/","by":{"3":"9"}},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"MCI Telecomms. Corp. v. Am. Tel. & Tel. Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"Nelson v. United States","cite":"40 F.4th 1105","y":2022,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/40/1105/","sum":"Holding that the “use of ‘statute’ alone” in 28 U.S.C. § 2412 “most naturally refers only to federal statutes”.","sumSrc":"brief:3","by":{"3":"9"}},{"t":"case","label":"Richmond Newspapers, Inc. v. Virginia","cite":"448 U.S. 555","y":1980,"id":"1979/79-243","sc":1,"sum":"In a 7-to-1 decision, the Court held that the right to attend criminal trials was \"implicit in the guarantees of the First Amendment.\" The Court held that the First Amendment encompassed not only the right to speak but also the freedom to listen and to receive information and ideas. The Court also noted that the First Amendment guaranteed the right of assembly in public places such as courthouses.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Sibbach v. Wilson & Co., Inc.","cite":"312 U.S 1","y":1941,"url":"https://www.courtlistener.com/c/U.S/312/1/","by":{"3":"7, 8"}},{"t":"case","label":"Truskett v. Closser","cite":"236 U.S. 223","y":1915,"id":"scdb/1914-210","sc":1,"sum":"The qualification “except as otherwise specifically provided by law,”. as used in § 6 of the act of May 27, 1908, 35 Stat. 312, removing restrictions upon alienation of allotments to members of the Five Civilized Tribes, means Federal, not state, law.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"12"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns, Inc.","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"ZF Auto. US, Inc. v. Luxshare, Ltd.","cite":"596 U.S. 619","y":2022,"id":"2021/21-401","sc":1,"sum":"Although 28 U. S. C. §1782(a) permits a district court to order discovery “for use in a proceeding in a foreign or international tribunal,” only a governmental or intergovernmental adjudicative body may qualify as such a tribunal, and the arbitration panels in these cases are not such adjudicative bodies.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"9, 10, 11, 14"}},{"t":"usc","label":"28 U.S.C. § 381","url":"https://www.law.cornell.edu/uscode/text/28/381","subs":["(1937)"],"by":{"3":"12"}},{"t":"rule","label":"Fed. R. Evid. 613","url":"https://www.law.cornell.edu/rules/fre/rule_613","subs":["(b)"],"by":{"3":"18"}}]};